const output = [];

for (const item of $input.all()) {
  const thread = item.json;

  const comment = thread.snippet?.topLevelComment;
  const snippet = comment?.snippet;

  // Skip malformed/incomplete comment threads
  if (!comment?.id || !snippet?.videoId || !snippet?.textOriginal) {
    continue;
  }

  output.push({
    json: {
      comment_id: comment.id,
      video_id: snippet.videoId,

      comment_text: snippet.textOriginal,

      like_count: Number(snippet.likeCount ?? 0),
      reply_count: Number(thread.snippet?.totalReplyCount ?? 0),

      published_at: snippet.publishedAt ?? null,
      updated_at: snippet.updatedAt ?? null,
    }
  });
}

return output;

const output = [];

for (const item of $input.all()) {
  const video = item.json;

  // A valid video ID is mandatory
  if (!video.id) {
    continue;
  }

  // Convert YouTube ISO 8601 duration (e.g. PT10M52S) to seconds
  let durationSeconds = null;

  if (video.duration) {
    const match = video.duration.match(
      /PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/
    );

    if (match) {
      durationSeconds =
        Number(match[1] ?? 0) * 3600 +
        Number(match[2] ?? 0) * 60 +
        Number(match[3] ?? 0);
    }
  }

  output.push({
    json: {
      video_id: video.id,
      search_phrase: video.searchPhrase ?? null,

      title: video.title ?? '',
      description: video.description ?? null,

      channel_id: video.channelId ?? null,
      channel_title: video.channelTitle ?? '',

      published_at: video.publishedAt ?? null,
      duration_seconds: durationSeconds,

      view_count:
        video.viewCount != null
          ? Number(video.viewCount)
          : null,

      like_count:
        video.likeCount != null
          ? Number(video.likeCount)
          : null,

      comment_count:
        video.commentCount != null
          ? Number(video.commentCount)
          : 0,

      youtube_url: `https://www.youtube.com/watch?v=${video.id}`,
    }
  });
}

return output;

const rawBody = $json.body ?? $json;

const body = Array.isArray(rawBody)
  ? rawBody[0]
  : rawBody;

const inputUrl =
  body?.inputs?.video ??
  body?.youtube_url ??
  body?.video ??
  body?.url ??
  null;

if (typeof inputUrl !== 'string' || !inputUrl.trim()) {
  throw new Error('Missing YouTube URL');
}

const url = inputUrl.trim();

const patterns = [
  /[?&]v=([A-Za-z0-9_-]{11})/,
  /youtu\.be\/([A-Za-z0-9_-]{11})/,
  /youtube\.com\/shorts\/([A-Za-z0-9_-]{11})/,
  /youtube\.com\/embed\/([A-Za-z0-9_-]{11})/,
  /youtube\.com\/live\/([A-Za-z0-9_-]{11})/
];

let videoId = null;

for (const pattern of patterns) {
  const match = url.match(pattern);

  if (match?.[1]) {
    videoId = match[1];
    break;
  }
}

if (!videoId) {
  throw new Error(
    `Could not extract YouTube video ID from: ${url}`
  );
}

return [
  {
    json: {
      video_id: videoId,
      youtube_url: `https://www.youtube.com/watch?v=${videoId}`
    }
  }
];

