const source = $('Loop Through Comments').item.json;
const decision = $json.answers?.classification;

const classification = decision?.choice;

if (!['PAIN', 'OPPORTUNITY', 'IRRELEVANT'].includes(classification)) {
  throw new Error(
    `Invalid classification: ${JSON.stringify(classification)}`
  );
}

return {
  json: {
    ...source,
    processing_status: 'processed',
    classification,
    classification_confidence: Number(decision.confidence ?? 0),
    classification_probabilities: decision.probabilities ?? {},
    classification_model: $json.model ?? null,
    classification_provider: $json.provider ?? null,
    classification_cost: Number($json.usage?.cost ?? 0)
  }
};

const items = $input.all();
const video = $('Normalize Video Data').first().json;

const systemPrompt = `
You are a market research signal writer.

You receive a YouTube comment that has already been classified as either PAIN or OPPORTUNITY.

Your task is only to write one concise business signal describing what the comment reveals.

Rules:
- Do not change or question the provided classification.
- Base the signal on the original comment.
- Use the video context only to understand ambiguous references.
- Do not invent information that is not stated or clearly implied.
- Write one concise sentence.
- For PAIN, describe the problem, friction, limitation, or negative experience.
- For OPPORTUNITY, describe the desired capability, improvement, use case, or opportunity.
- Do not include the words PAIN or OPPORTUNITY in the signal.
- Do not add explanations or reasoning.

Return exactly one valid JSON object:

{
  "signal": "Concise business signal"
}
`;

return items.map(item => {
  const comment = item.json;

  const userPrompt = `
VIDEO CONTEXT

Video title:
${video.title}

COMMENT CLASSIFICATION

${comment.classification}

COMMENT

${comment.comment_text}
`;

  return {
    json: {
      ...comment,
      system_prompt: systemPrompt.trim(),
      user_prompt: userPrompt.trim()
    }
  };
});

const analysisItems = $input.all();
const sourceItems = $('Prepare Signal Generation').all();

if (analysisItems.length !== sourceItems.length) {
  throw new Error(
    `Signal count mismatch: received ${analysisItems.length} LLM outputs ` +
    `for ${sourceItems.length} comments`
  );
}

const output = [];

for (let i = 0; i < analysisItems.length; i++) {
  const source = sourceItems[i].json;
  const llmItem = analysisItems[i].json;

  if (
    source.classification !== 'PAIN' &&
    source.classification !== 'OPPORTUNITY'
  ) {
    throw new Error(
      `Unexpected classification ${JSON.stringify(source.classification)} ` +
      `for comment ${source.comment_id}`
    );
  }

  let parsed;

  if (
    llmItem &&
    typeof llmItem === 'object' &&
    typeof llmItem.signal === 'string'
  ) {
    parsed = llmItem;
  } else {
    let raw =
      llmItem?.text ??
      llmItem?.output ??
      llmItem?.response ??
      llmItem;

    if (typeof raw !== 'string') {
      throw new Error(
        `Invalid signal output type for comment ${source.comment_id}`
      );
    }

    raw = raw
      .trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/, '')
      .replace(/\s*```$/, '')
      .trim();

    try {
      parsed = JSON.parse(raw);
    } catch (error) {
      throw new Error(
        `Invalid JSON for comment ${source.comment_id}: ${error.message}`
      );
    }
  }

  if (
    typeof parsed.signal !== 'string' ||
    !parsed.signal.trim()
  ) {
    throw new Error(
      `Missing signal for ${source.classification} comment ${source.comment_id}`
    );
  }

  output.push({
    json: {
      comment_id: source.comment_id,
      video_id: source.video_id,
      comment_text: source.comment_text,
      like_count: source.like_count,
      reply_count: source.reply_count,
      published_at: source.published_at,
      updated_at: source.updated_at,
      processing_status: 'processed',
      classification: source.classification,
      classification_confidence: source.classification_confidence,
      classification_probabilities: source.classification_probabilities,
      classification_model: source.classification_model,
      classification_provider: source.classification_provider,
      classification_cost: source.classification_cost,
      signal: parsed.signal.trim()
    }
  });
}

return output;

const source = $('Loop Through Comments').item.json;

const errorMessage =
  $json?.error?.message ??
  $json?.error?.description ??
  $json?.message ??
  $json?.error ??
  'Unknown processing error';

return {
  json: {
    comment_id: source.comment_id,
    video_id: source.video_id,
    comment_text: source.comment_text,
    like_count: source.like_count,
    reply_count: source.reply_count,
    published_at: source.published_at,
    updated_at: source.updated_at,
    processing_status: 'error',
    error_message:
      typeof errorMessage === 'string'
        ? errorMessage
        : JSON.stringify(errorMessage)
  }
};

const items = $input.all().map(item => item.json);
const video = $('Normalize Video Data').first().json;

const errors = items.filter(
  item => item.processing_status === 'error'
);

const processed = items.filter(
  item => item.processing_status === 'processed'
);

const pains = processed.filter(
  item => item.classification === 'PAIN'
);

const opportunities = processed.filter(
  item => item.classification === 'OPPORTUNITY'
);

const irrelevant = processed.filter(
  item => item.classification === 'IRRELEVANT'
);

const relevant = [...pains, ...opportunities];

const formatComment = (row, index) => {
  const comment = String(row.comment_text ?? '')
    .split('\n')
    .map(line => `> ${line}`)
    .join('\n');

  return [
    `### ${index + 1}. ${row.signal}`,
    '',
    comment,
    '',
    `*Likes: ${Number(row.like_count ?? 0)} · Replies: ${Number(row.reply_count ?? 0)}*`
  ].join('\n');
};

const sections = [
  '# YouTube Signal Report',
  '',
  `**Video:** ${video.title}`,
  `**Channel:** ${video.channel_title}`,
  `**URL:** ${video.youtube_url}`,
  '',
  '## Processing Summary',
  '',
  `- Comments received: ${items.length}`,
  `- Successfully processed: ${processed.length}`,
  `- Errors: ${errors.length}`,
  `- Pain signals: ${pains.length}`,
  `- Opportunity signals: ${opportunities.length}`,
  `- Irrelevant comments: ${irrelevant.length}`,
  '',
  `## Pain (${pains.length})`,
  '',
  pains.length
    ? pains.map(formatComment).join('\n\n')
    : '_No pain signals identified._',
  '',
  `## Opportunities (${opportunities.length})`,
  '',
  opportunities.length
    ? opportunities.map(formatComment).join('\n\n')
    : '_No opportunity signals identified._'
];

if (errors.length) {
  sections.push(
    '',
    '## Processing Errors',
    '',
    `${errors.length} comment${errors.length === 1 ? '' : 's'} could not be processed.`
  );
}

const text = sections.join('\n');

const signals = relevant.map(row => ({
  comment_id: row.comment_id,
  classification: row.classification,
  signal: row.signal,
  comment_text: row.comment_text,
  like_count: Number(row.like_count ?? 0),
  reply_count: Number(row.reply_count ?? 0),
  published_at: row.published_at ?? null,
  updated_at: row.updated_at ?? null,
  classification_confidence: row.classification_confidence ?? null,
  classification_probabilities: row.classification_probabilities ?? null,
  classification_model: row.classification_model ?? null,
  classification_provider: row.classification_provider ?? null,
  classification_cost: Number(row.classification_cost ?? 0)
}));

const processingErrors = errors.map(row => ({
  comment_id: row.comment_id ?? null,
  comment_text: row.comment_text ?? null,
  error_message: row.error_message ?? 'Unknown processing error'
}));

return [
  {
    json: {
      text,
      json: {
        video: {
          video_id: video.video_id,
          title: video.title,
          channel_id: video.channel_id,
          channel_title: video.channel_title,
          published_at: video.published_at,
          duration_seconds: video.duration_seconds,
          view_count: video.view_count,
          like_count: video.like_count,
          comment_count: video.comment_count,
          youtube_url: video.youtube_url
        },
        summary: {
          total_comment_count: items.length,
          processed_comment_count: processed.length,
          error_count: errors.length,
          relevant_signal_count: relevant.length,
          pain_count: pains.length,
          opportunity_count: opportunities.length,
          irrelevant_count: irrelevant.length
        },
        signals,
        errors: processingErrors
      }
    }
  }
];
